"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["83191"],{45775(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.desempate_obrigatorio","status":422,"titulo":"O crit\xe9rio de maioria, em banca com mais de um integrante, declara o desempate"},"descricao":{"codigo":"uniplus.selecao.banca.desempate_obrigatorio","requisitos":["UNI-REQ-0275","UNI-REQ-0400"],"oQueAconteceu":["A recusa tamb\xe9m ocorre quando o c\xf3digo informado n\xe3o corresponde a uma das op\xe7\xf5es aceitas.","A banca decide por maioria (`MAIORIA_SIMPLES` ou `MAIORIA_ABSOLUTA`), tem 2 ou mais\\nintegrantes e n\xe3o declara a forma de desempate. Com mais de um integrante a\\nvota\xe7\xe3o pode empatar, e o edital precisa dizer o que acontece ent\xe3o\\n(UNI-REQ-0275). Uma banca de 4 integrantes com maioria simples e sem desempate\\nfica sem resposta para o empate de 2 a 2.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.desempate` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.desempate` na banca da etapa."],"comoResolver":["Informe no campo `desempate` a forma do edital: `VOTO_DA_PRESIDENCIA` ou\\n`NOVA_VOTACAO`. Se o crit\xe9rio n\xe3o \xe9 de maioria, o campo n\xe3o se aplica; ver\\n[desempate n\xe3o se aplica](/erros/uniplus.selecao.banca.desempate_nao_se_aplica)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);